def get_tile_data(tile_type):
	sprite = tiles.get(tile_type)
	if sprite:
		return sprite, False, False, 8, 8
	override = _tile_flip_overrides.get(tile_type)
	if override:
		base, x_flip, y_flip = override
		sprite = tiles.get(base)
		if sprite:
			return sprite, x_flip, y_flip, 8, 8
	return None, False, False, 8, 8

